	@Test
	void copyRechecksMembershipAndDoesNotSkipDeletedContinuationOrLoseSnapshot(@TempDir Path directory)
			throws Exception {
		seed(directory, 600);
		try (ControlledStore store = new ControlledStore(directory, "posc,cspo");
				Txn old = store.getTxnManager().createReadTxnUntracked()) {
			store.pauseRead = true;
			store.startBackgroundIndexRebuild();
			await(store.read);
			long[] continuation = store.lastReadQuad.clone();
			synchronized (store.writerLock) {
				store.startTransaction();
				store.removeTriplesByContext(1, -1, -1, -1, true, quad -> {
				});
				store.removeTriplesByContext(continuation[0], continuation[1], continuation[2], continuation[3],
						true, quad -> {
						});
				store.storeTriple(0, 2, 9_000, 0, true); // behind the source continuation
				store.storeTriple(700, 2, 1_700, 0, true); // inferred -> explicit promotion
				store.storeTriple(801, 2, 1_801, 0, false);
				store.storeTriplesAligned(new long[] { 1_001, 1_002 }, new long[] { 2, 2 },
						new long[] { 2_001, 2_002 }, new long[] { 0, 0 }, 2, true);
				store.commit();
				store.startTransaction();
				store.storeTriple(9_999, 2, 10_999, 0, true);
				store.rollback();
			}
			store.release.countDown();
			await(store.published);
			assertEquals(600, store.countTriples(old, -1, -1, -1, -1, true));
			assertTrue(store.hasTriples(old, 1, 2, 1_001, 0, true));
			assertEquals("spoc", store.getIndexName(old, -1, 2, -1, -1));
			try (Txn current = store.getTxnManager().createReadTxn()) {
				assertEquals(602, store.countTriples(current, -1, -1, -1, -1, true));
				assertEquals(1, store.countTriples(current, -1, -1, -1, -1, false));
				assertFalse(store.hasTriples(current, 1, 2, 1_001, 0, true));
				assertFalse(store.hasTriples(current, continuation[0], continuation[1], continuation[2],
						continuation[3], true));
				assertFalse(store.hasTriples(current, 9_999, 2, 10_999, 0, true));
				assertTrue(store.hasTriples(current, 0, 2, 9_000, 0, true));
				assertEquals(602, count(store.getTriples(current, -1, -1, -1, -1, true)));
			}
			old.close();
			assertTrue(store.awaitIndexRebuild(10, TimeUnit.SECONDS), store.indexRebuildStatus());
			assertEquals(Set.of("posc", "cspo"), store.explicitIndexEntryCounts().keySet());
		}
	}

