	@Test
	void preparedNativeChunkAndRawBulkMutationsMaintainStagingAndReencodeOldPlans(@TempDir Path directory)
			throws Exception {
		seed(directory, 600);
		try (ControlledStore store = new ControlledStore(directory, "posc,cspo");
				var executor = Executors.newFixedThreadPool(4)) {
			store.pauseRead = true;
			store.startBackgroundIndexRebuild();
			await(store.read);
			long[] subjects = { 8_001, 8_002 };
			long[] predicates = { 2, 2 };
			long[] objects = { 18_001, 18_002 };
			long[] contexts = { 0, 0 };
			var prepared = store.prepareSecondaryIndexesAsync(executor, subjects, predicates, objects, contexts, 2);
			long[] laterSubjects = { 8_101, 8_102 };
			var stale = store.prepareSecondaryIndexesAsync(executor, laterSubjects, predicates, objects, contexts, 2);
			var staleMain = stale.awaitMain();
			try {
				synchronized (store.writerLock) {
					store.startTransaction();
					store.storePreparedTriples(subjects, predicates, objects, contexts, 2, true, true, null,
							prepared.awaitMain(), prepared::await);
					store.commit();
					store.startTransaction(store.prepareReplayDecision().forNativeCheckpoints());
					store.storeTriplesAligned(new long[] { 9_001, 9_002 }, predicates, objects, contexts, 2, true);
					store.removeNativeChunkQuads(new long[][] { { 2, 2, 1_002, 0 }, { 3, 2, 1_003, 0 } }, true,
							row -> {
							});
					store.commit();
					store.startTransaction(store.prepareReplayDecision().forNativeCheckpoints());
					store.storeTriple(9_999, 2, 19_999, 0, true);
					store.rollback();
					int[] row = { 0 };
					assertEquals(2, store.appendBulkIndex("spoc", tuple -> {
						if (row[0] == 2) {
							return false;
						}
						tuple[0] = 9_003 + row[0];
						tuple[1] = 2;
						tuple[2] = 19_003 + row[0];
						tuple[3] = 10 + row[0]++;
						return true;
					}, 1, 1_024));
					row[0] = 0;
					store.appendBulkContexts(contextAndCount -> {
						if (row[0] == 2) {
							return false;
						}
						contextAndCount[0] = 10 + row[0]++;
						contextAndCount[1] = 1;
						return true;
					}, 1, 1_024);
				}
				store.release.countDown();
				assertTrue(store.awaitIndexRebuild(10, TimeUnit.SECONDS), store.indexRebuildStatus());
				store.startTransaction();
				store.storePreparedTriples(laterSubjects, predicates, objects, contexts, 2, true, true, null,
						staleMain, stale::await);
				store.commit();
				assertEquals(Set.of(606L), Set.copyOf(store.explicitIndexEntryCounts().values()));
				try (Txn txn = store.getTxnManager().createReadTxn()) {
					assertEquals(606, count(store.getTriples(txn, -1, -1, -1, -1, true)));
					assertEquals(606, count(store.getTriples(txn, -1, 2, -1, -1, true)));
					assertTrue(store.hasTriples(txn, 8_101, 2, 18_001, 0, true));
					assertFalse(store.hasTriples(txn, 2, 2, 1_002, 0, true));
					assertFalse(store.hasTriples(txn, 9_999, 2, 19_999, 0, true));
				}
			} finally {
				store.release.countDown();
				staleMain.close();
				prepared.cancel();
				stale.cancel();
			}
		}
	}

	@ParameterizedTest
	@ValueSource(ints = { 3, 8_192 })
	void malformedFormatCertificateFailsClosedWithoutChangingAuthority(int certificateBytes,
			@TempDir Path directory) throws Exception {
		seed(directory, 600);
		Map<String, Map<String, String>> original;
		try (TripleStore store = new TripleStore(directory.toFile(), config("spoc"), null)) {
			original = adjacencyAuthority(store);
		}
		byte[] validFormat = HexFormat.of().parseHex(original.get("metadata").get("00"));
		writeFormatCertificate(directory, new byte[certificateBytes]);
		Map<String, String> corruptImage = LmdbCompatibilityFixtures.snapshot(directory);
		IOException failure = assertThrows(IOException.class, () -> {
			try (TripleStore ignored = new TripleStore(directory.toFile(), config("posc"), null)) {
				throw new AssertionError("malformed authoritative format must be rejected");
			}
		});
		assertEquals(certificateBytes > 64 ? "Invalid persistent adjacency scalar value length"
				: "Unsupported or incomplete persistent adjacency format", failure.getMessage());
		assertEquals(corruptImage, LmdbCompatibilityFixtures.snapshot(directory),
				"failed admission cannot mutate authority; volatile lock files are excluded");
		writeFormatCertificate(directory, validFormat);
		try (TripleStore recovered = new TripleStore(directory.toFile(), config("cspo"), null)) {
			assertEquals(original, adjacencyAuthority(recovered));
			assertNativeSchemaAndRows(recovered, "cspo", seededModel(600));
			assertIdleMaintenanceIsReadOnly(recovered);
		}
	}

